#include <iostream>
#include <string>
#include <map>
#include <vector>
using namespace std;

class Cart;
class User;
class Flags;
class Item;

static const map<string, double> MEMBERSHIP_DISCOUNTS = { {"gold", 0.2}, {"silver", 0.1} };

double membershipDiscount(User* user, bool hasCoupon) {
    auto it = MEMBERSHIP_DISCOUNTS.find(user->getMembership());
    if (it != MEMBERSHIP_DISCOUNTS.end()) {
        return it->second;
    }
    return hasCoupon ? 0.05 : 0;
}

double inStockTotal(vector<Item*> items) {
    double total = 0;
    for (Item* item : items) {
        if (item->isInStock()) total += item->getPrice();
    }
    return total;
}

double electronicsBonusDiscount(vector<Item*> items, double runningTotal) {
    bool hasElectronics = false;
    for (Item* item : items) {
        if (item->getCategory() == "electronics") { hasElectronics = true; break; }
    }
    bool hasBigElectronicsOrder = hasElectronics && runningTotal > 1000;
    return hasBigElectronicsOrder ? 0.02 : 0;
}

double processCheckout(Cart* cart, User* user, Flags* flags) {
    if (!user->isLoggedIn()) {
        return inStockTotal(cart->getItems());
    }
    double subtotal = inStockTotal(cart->getItems());
    double discount = membershipDiscount(user, flags->hasCoupon()) + electronicsBonusDiscount(cart->getItems(), subtotal);
    return subtotal - subtotal * discount;
}

