        if (tier == "gold") return new GoldDiscountStrategy();
        if (tier == "silver") return new SilverDiscountStrategy();
        throw invalid_argument("unknown tier");
    }
};

double discountFor(string tier, double amount) {
    DiscountStrategy* strategy = DiscountStrategyFactory::create(tier);
    return strategy->calculate(amount);
}

