}
string checkPassword(map<string, string> d) {
    return (d.find("password") == d.end() || d["password"].length() < 8) ? "password too short" : "";
}
string checkName(map<string, string> d) {
    return (d.find("name") == d.end() || d["name"].empty()) ? "name required" : "";
}
string checkBio(map<string, string> d) {
    return (d.find("bio") == d.end() || d["bio"].length() > 500) ? "bio too long" : "";
}

