#include <iostream>
#include <string>
#include <map>
#include <chrono>
#include <optional>
using namespace std;

class Order;

enum class OrderStatus { PENDING, PROCESSING, SHIPPED };

static const long long MILLISECONDS_PER_DAY = 86400 * 1000LL;
static const map<OrderStatus, int> SHIPPING_DAYS = { {OrderStatus::PENDING, 3}, {OrderStatus::PROCESSING, 1} };
static const map<string, double> TAX_RATE_BY_REGION = { {"CA", 1.0725}, {"NY", 1.08875} };
static const double DEFAULT_TAX_RATE = 1.05;

optional<long long> calculateShippingEta(Order* order) {
    auto it = SHIPPING_DAYS.find(order->getStatus());
    if (it == SHIPPING_DAYS.end()) return nullopt;
    long long now = chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now().time_since_epoch()).count();
    return now + it->second * MILLISECONDS_PER_DAY;
}

double applyTax(double amount, string region) {
    auto it = TAX_RATE_BY_REGION.find(region);
    return amount * (it != TAX_RATE_BY_REGION.end() ? it->second : DEFAULT_TAX_RATE);
}
